 if(!inspect)({inspectVolcSigner:inspect}=await import(pathToFileURL(path.resolve(root,'scripts/signer-volc-deploy.mjs')).href));
 const live=await inspect({command:'detail',functionId:FUNCTION});
 if(live.cloud_account_id!==ACCOUNT||live.function_id!==FUNCTION)throw Error('readback_cloud_identity_mismatch');
 return {schema:'ltzzz.volc-signer.live-readback.v1',task_id:TASK,step_id:'SPLIT-SIGNER-INFRA-20261026',request_id:request.request_id,
  at_utc:new Date(now).toISOString(),source_commit:sourceCommit,approved_probe_commit:APPROVED,probe_sources,run_id:runId,run_attempt:runAttempt,
  observation:publicReadbackProjection(live),private_keys_read:false,cloud_writes:0,model_calls:0,production_deployed:false,public_key_registered:false,
  reader_inventory_verified:false,actual_source_bytes_verified:false,restart_same_key_verified:false,native_doubao_signature_verified:false,
  financial_execution:false,paid:false,tx_hash:null};
}

name: Volc signer one-time live readback (read only)
on:
  pull_request:
    paths: ['scripts/run-volc-live-readback.mjs','scripts/tests/volc-live-readback.test.mjs','.github/workflows/volc-signer-live-readback.yml']
  push:
    branches: [main]
    paths: ['ops/dispatch/runtime-requests/volc-signer-readback.json']
permissions: {contents: read}
concurrency: {group: volc-signer-live-readback, cancel-in-progress: false}
jobs:
  offline:
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683
        with: {persist-credentials: false}
      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020
        with: {node-version: '22'}
      - run: node --test scripts/tests/volc-live-readback.test.mjs scripts/tests/volc-signer-closeout.test.mjs
  readback:
    needs: offline
    if: github.event_name == 'push' && github.ref == 'refs/heads/main' && github.repository == 'ltzyz2181-collab/ltzzz'
    runs-on: ubuntu-latest
    timeout-minutes: 3
    steps:
      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683
        with: {persist-credentials: false, ref: '${{ github.sha }}'}
      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020
        with: {node-version: '22'}
      - name: Validate one-hour request and exact Claude-approved source before credentials
        run: node scripts/run-volc-live-readback.mjs validate
      - name: Read fixed existing function without deployment, key access or model calls
        env:
          VOLC_ACCESS_KEY: ${{ secrets.VOLC_ACCESS_KEY }}
          VOLC_SECRET_KEY: ${{ secrets.VOLC_SECRET_KEY }}
        run: node scripts/run-volc-live-readback.mjs run
      - uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02
        if: always()
        with:
          name: volc-live-readback-${{ github.run_id }}-${{ github.run_attempt }}
          path: results/volc-signer/live-readback.json
          if-no-files-found: error
          retention-days: 30


CLI逻辑：从固定 ops/dispatch/runtime-requests/volc-signer-readback.json 读JSON，validateReadbackRequest和verifyApprovedProbe均先执行；mode=validate时只输出校验结果，mode=run时调用runReadback。异常只输出受限小写错误枚举或generic，绝不回显异常文本/云原文。runID/attempt/source来自Actions。唯一输出results/volc-signer/live-readback.json和同一JSON stdout。publicReadbackProjection丢弃任意云字段：只保留固定身份、NAS挂载布尔、受限runtime/时间、版本计数/ID/大小。触发器url再次解析并强制官方北京网关合法子域、HTTP(S)默认端口；仅/、/health、/challenge、/attest显示pathname；其他路径只显示origin+/并标记nonstandard_path_omitted；userinfo/query/fragment都不输出。解析异常返回null，不访问URL。
原workflow只有手动dispatch但当前连接无该写接口；不能用旧未脱敏detail的历史commit重跑，因此加一次性请求push，非永久新cron。请求文件将在此PR合并后独立提交，此PR合并不触发云调用。现有云IAMSecret仅进main job；没有ARK key/钱包/A2/付款或信任根变更。7项新测试加原61项合计68通过，覆盖过期/越界/源码改动先失败，错误账号不能核验，非标准路径和任意环境字段不公开，测试不碰云。
